"use strict";
const {test}=require("node:test"),{spawn}=require("node:child_process"),{once}=require("node:events"),S=require("./support.cjs"),{assert}=S;
function child(control,stage){const args=[...process.execArgv.filter(x=>!x.startsWith('--test')),S.path.join(__dirname,"crash-worker.cjs"),control,stage];const p=spawn(process.execPath,args,{env:process.env,stdio:["ignore","pipe","pipe","ipc"]});const messages=[],waiters=[];let stdout="",stderr="";p.stdout.on("data",x=>stdout+=x);p.stderr.on("data",x=>stderr+=x);p.on("message",m=>{messages.push(m);for(const w of waiters)w(m);});const ended=once(p,"exit");return{p,args,messages,ended,output:()=>({stdout,stderr}),wait(kind){const old=messages.find(x=>x.kind===kind);if(old)return Promise.resolve(old);return new Promise((resolve,reject)=>{const timer=setTimeout(()=>{p.kill();reject(Error('Child did not reach '+kind+': '+JSON.stringify(messages)+stderr));},15000);waiters.push(m=>{if(m.kind==='error'){clearTimeout(timer);reject(Error(JSON.stringify(m)));}if(m.kind===kind){clearTimeout(timer);resolve(m);}});});}};}
async function snapshots(directory){const out={};for(const n of await S.fs.readdir(directory)){const p=S.path.join(directory,n);if((await S.fs.lstat(p)).isFile()){const raw=await S.fs.readFile(p);out[n]={bytes:raw.toString('base64'),sha256:S.crypto.createHash('sha256').update(raw).digest('hex')};}}return out;}
test("actual independent process cannot acquire a live owner lease",async t=>{const f=await S.fixture(t),control=S.path.join(S.audit,S.crypto.randomUUID()+'.json');await S.fs.writeFile(control,JSON.stringify({config:f.cfg}));const c=child(control,'contend'),message=await c.wait('contention'),[code,signal]=await c.ended;assert.equal(message.code,'LOCK_HELD');assert.equal(code,0);assert.equal(signal,null);});
for(const stage of ['before-publication','after-temp-creation','after-flush','before-replacement','after-replacement','before-acknowledgement','during-reconciliation'])test("parent-terminated actual persistence: "+stage,async t=>{
 const f=await S.fixture(t);let request=null;if(stage==='during-reconciliation'){request=S.request(f,await S.read(f));assert.equal((await f.store.transact(request)).status,'committed');}await f.store.close();
 const dir=S.path.join(S.audit,'interruptions',stage+'-'+S.crypto.randomUUID());await S.fs.mkdir(dir,{recursive:true});const control=S.path.join(dir,'control.json');await S.fs.writeFile(control,JSON.stringify({config:f.cfg,request}));const c=child(control,stage);const original=await c.wait('request'),paused=await c.wait('paused');assert.equal(paused.stage,stage);request=original.request;const lockPath=S.path.join(f.directory,'APPLICATION.lock'),raw=await S.fs.readFile(lockPath),lock=JSON.parse(raw);assert.equal(lock.pid,c.p.pid);assert.equal(lock.host,S.os.hostname());S.C.uuid(lock.token);const before=await snapshots(f.directory);await S.fs.writeFile(S.path.join(dir,"pause-evidence.json"),JSON.stringify({command:{executable:process.execPath,args:c.args},stage,pid:lock.pid,host:lock.host,token:lock.token,files:before,request},null,2));const killed=c.p.kill();assert(killed);const [exitCode,signal]=await c.ended;assert(c.p.exitCode!==null||c.p.signalCode!==null);assert.throws(()=>process.kill(lock.pid,0));assert.deepEqual(await S.fs.readFile(lockPath),raw);
 await S.fs.writeFile(S.path.join(dir,'before-lock-movement.json'),JSON.stringify({command:{executable:process.execPath,args:c.args},stage,pid:lock.pid,host:lock.host,token:lock.token,lockBytes:raw.toString('base64'),lockSha256:S.crypto.createHash('sha256').update(raw).digest('hex'),exitCode,signal,deathProven:true,files:before,request,...c.output()},null,2));
 // Exact dead-child lock only; evidence was preserved and death proved above.
 await S.fs.rename(lockPath,S.path.join(f.directory,'.dead-application-lock-'+lock.token));
 await f.store.open({version:1});const out=await f.store.reconcile(request),committed=['after-replacement','before-acknowledgement','during-reconciliation'].includes(stage);assert.equal(out.status,committed?'replayed':'unknown');const replay=await f.store.transact(request);assert.equal(replay.status,committed?'replayed':'unknown');const data=await S.disk(f);assert.equal(data.revision,committed?1:0);assert.equal(data.receipts.length,committed?1:0);assert.equal(data.data.workspaceMode.value,committed?1:0);await f.store.close();await S.fs.writeFile(S.path.join(dir,'reconciliation.json'),JSON.stringify({out,replay,files:await snapshots(f.directory)},null,2));
});
